from typing import List, Optional


def longest(strings: List[str]) -> Optional[str]:
    """Return the longest string from a list. If there are multiple strings with the same maximum length,
    return the first one. Return None if the list is empty."""

    if not strings:
        return None

    max_length = max(len(s) for s in strings)
    return next((s for s in strings if len(s) == max_length), None)

