import random

def miller_rabin(n, k=10):
    """
    Test if n is prime using the Miller-Rabin primality test.
    """
    if n < 2:
        return False
    if n == 2 or n == 3:
        return True
    if n % 2 == 0:
        return False

    r = 0
    d = n - 1
    while d % 2 == 0:
        r += 1
        d //= 2

    for _ in range(k):
        a = random.randint(2, n - 2)
        x = pow(a, d, n)
        if x == 1 or x == n - 1:
            continue
        for _ in range(r - 1):
            x = pow(x, 2, n)
            if x == n - 1:
                break
        else:
            return False

    return True

def prime_fib(n: int) -> int:
    """
    prime_fib returns the n-th number that is both a Fibonacci number and prime.
    """
    count_primes_found = 0
    fib_a, fib_b = 0, 1

    while count_primes_found < n:
        fib_a, fib_b = fib_b, fib_a + fib_b
        if miller_rabin(fib_b):
            count_primes_found += 1

    return fib_b

