import string

def shift_character(ch: str, shift: int) -> str:
    """
    Helper function to shift a single character by a given number of positions in the alphabet.
    """
    if ch not in string.ascii_lowercase:
        raise ValueError("Input must be a lowercase letter.")

    shifted_position = (string.ascii_lowercase.index(ch) + shift) % 26
    return string.ascii_lowercase[shifted_position]

def encode_shift(s: str) -> str:
    """
    Encodes a string by shifting each character by 5 positions forward in the alphabet.
    """
    return ''.join(shift_character(ch, 5) for ch in s)

def decode_shift(s: str) -> str:
    """
    Decodes a string that was encoded with the encode_shift function by shifting each character 
    5 positions backward in the alphabet.
    """
    return ''.join(shift_character(ch, -5) for ch in s)

