def is_multiply_prime(number):
    """
    Determines if the given number is the product of exactly three prime numbers.

    Args:
    number (int): The number to check. It is assumed to be less than 100.

    Returns:
    bool: True if the number is the product of three prime numbers, False otherwise.
    """

    def is_prime(n):
        """Check if a number is prime."""
        if n <= 1:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True

    prime_factors = []
    for i in range(2, number + 1):
        if number % i == 0 and is_prime(i):
            prime_factors.append(i)
            while number % i == 0:
                number //= i

    return len(prime_factors) == 3

