def encrypt(s):
    """
    Encrypts a given string by rotating the alphabet by four positions.

    Args:
    s (str): The input string to be encrypted.

    Returns:
    str: The encrypted string.
    """
    ALPHABET = 'abcdefghijklmnopqrstuvwxyz'
    ROTATION = 4

    def rotate_char(c):
        if c in ALPHABET:
            return chr((ord(c) - ord(ALPHABET[0]) + ROTATION) % len(ALPHABET) + ord(ALPHABET[0]))
        return c

    return ''.join(map(rotate_char, s))

