def encode(message):
    """
    Encodes a given message by swapping the case of all letters and replacing each vowel with the letter two places ahead in the English alphabet.

    Args:
    message (str): The input string to be encoded.

    Returns:
    str: The encoded string.
    """

    def swap_case(character):
        """Swaps the case of the given character."""
        if character.isupper():
            return character.lower()
        elif character.islower():
            return character.upper()
        else:
            return character

    def replace_vowel(character):
        """Replaces the vowel with the letter two places ahead in the English alphabet."""
        vowels = "aeiouAEIOU"
        if character in vowels:
            index = vowels.index(character)
            return chr(ord(vowels[index]) + 2)
        return character

    # Apply the transformations
    swapped_message = ''.join(map(swap_case, message))
    encoded_message = ''.join(map(replace_vowel, swapped_message))

    return encoded_message

