def unique_digits(numbers):
    """
    Given a list of positive integers, returns a sorted list of all elements that do not contain any even digits.

    Note: The returned list should be sorted in increasing order.

    For example:
    >>> unique_digits([15, 33, 1422, 1])
    [1, 15, 33]
    >>> unique_digits([152, 323, 1422, 10])
    []
    """

    def has_no_even_digit(number):
        for digit in str(number):
            if int(digit) % 2 == 0:
                return False
        return True

    return sorted(filter(has_no_even_digit, numbers))

