    Determines if a list of numbers is sorted in ascending order and contains no more than one duplicate of any number.

    Args:
    lst (list): A list of integers.

    Returns:
    bool: True if the list is sorted and contains no more than one duplicate, False otherwise.
    """

    # Dictionary to count occurrences of each number
    count = {}
    for num in lst:
        if num in count:
            count[num] += 1
            if count[num] > 2:
                return False
        else:
            count[num] = 1

    # Check if the list is sorted
    return lst == sorted(lst)

