def is_nested(brackets: str) -> bool:
    """
    Determines if there exists a valid subsequence of brackets where at least one bracket is nested.

    :param brackets: A string containing only square brackets.
    :return: True if such a subsequence exists, False otherwise.
    """

    for start_index in range(len(brackets)):
        if brackets[start_index] != '[':
            continue

        nesting_level = 0
        max_nesting = 0

        for end_index in range(start_index, len(brackets)):
            if brackets[end_index] == '[':
                nesting_level += 1
            elif brackets[end_index] == ']':
                nesting_level -= 1

            max_nesting = max(max_nesting, nesting_level)

            if nesting_level == 0:
                if max_nesting > 1:
                    return True
                break

    return False

